<?php $requestList=array_reverse($data['appointments']);$waitingRequests=count(array_filter($requestList,fn($appointment)=>appointment_status($data,$appointment)==='pending'));?>
<div class="page-heading request-page-heading"><div><span class="eyebrow">KLIENTËT</span><h1>Kërkesat për termin</h1><p>Shqyrto rezervimet, kontakto klientin dhe përcille punën deri në përfundim.</p></div><div class="request-count-chip"><strong><?=count($requestList)?></strong><span><?=$waitingRequests?> në pritje<br>kërkesa gjithsej</span></div></div>
<?php if($requestList):?><section class="request-card-list">
<?php foreach($requestList as $a):$st=appointment_status($data,$a);$v=vehicle_by_id($data,(int)$a['vehicle_id']);$requestCustomer=null;foreach($data['customers'] as $customerRow)if((int)$customerRow['id']===(int)$a['customer_id']){$requestCustomer=$customerRow;break;}$statusLabels=['pending'=>'Në pritje','accepted'=>'E pranuar','in_progress'=>'Në proces','completed'=>'Përfunduar','declined'=>'Refuzuar'];?>
<article class="request-card"><header class="request-card-header"><div><span class="request-id">KËRKESË #<?=h((string)$a['id'])?></span><h2><?=h(customer_name($data,(int)$a['customer_id']))?></h2></div><div class="request-header-meta"><span class="status-pill <?=h($st)?>"><?=h($statusLabels[$st]??$st)?></span><span class="request-date">Termin i kërkuar: <b><?=h(date('d.m.Y',strtotime($a['requested_date'])))?></b></span></div></header>
  <div class="request-card-body"><div class="request-detail"><small>AUTOMJETI</small><div class="request-vehicle-title"><?=vehicle_logo_html($v,'request-car-logo')?> <strong><?=h(vehicle_label($data,(int)$a['vehicle_id']))?></strong></div><?php if(!empty($v['year'])):?><span>Viti <?=h((string)$v['year'])?> · <?=number_format((int)($v['mileage']??0))?> km</span><?php endif;?></div><div class="request-detail request-problem"><small>SHËRBIMI DHE SIMPTOMAT</small><p><?=h($a['problem'])?></p></div><div class="request-detail request-contact"><small>KONTAKTI</small><strong><?=h($v?customer_name($data,(int)$a['customer_id']):'Klient')?></strong><span><?=h($requestCustomer['phone']??'Pa numër telefoni')?></span></div></div>
  <footer class="request-card-footer"><?php if($st==='pending'):?><span>Prano kërkesën për ta hapur si punë në servis.</span><div class="request-actions"><form method="post"><?php form_token();?><input type="hidden" name="action" value="appointment_start"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn primary">Prano dhe nis puna <span>→</span></button></form><form method="post" onsubmit="return confirm('A dëshiron ta refuzosh këtë kërkesë?')"><?php form_token();?><input type="hidden" name="action" value="appointment_update"><input type="hidden" name="status" value="declined"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn request-decline">Refuzo</button></form></div><?php elseif($st==='completed'):?><span>Kjo kërkesë u përfundua. Klienti mund ta shohë faturën te historiku i vet.</span><a class="text-link" href="?page=workshop">Shiko detajet e punës →</a><?php elseif($st==='in_progress'||$st==='accepted'):?><span>Plotëso diagnozën, statusin dhe faturën e kësaj pune.</span><a class="btn primary" href="?page=workshop">Vazhdo te puna <span>→</span></a><?php else:?><span>Kërkesa është refuzuar.</span><?php endif;?></footer>
</article>
<?php endforeach;?></section><?php else:?><section class="panel request-empty"><span>✉</span><h2>Nuk ka kërkesa për termin</h2><p>Kur klientët rezervojnë termin, kërkesat e tyre do të shfaqen këtu.</p></section><?php endif;?>
